 int score103(){int s=100;float t=temp(),baseRam=p.getFloat("base_ram",ram());if(t>=hotTemp())s-=25;else if(t>=warnTemp())s-=10;if(ram()>=97&&ram()>baseRam+15)s-=10;else if(ram()>=95&&ram()>baseRam+10)s-=5;if(free()<5)s-=20;else if(free()<10)s-=10;if(level()<10)s-=8;if(!shOk())s-=5;if(!signatureOk())s-=20;return Math.max(0,s);}
