 void job103(){base("🚗 JOBBPASS 2.0","Körtid • förbrukning • temperatur",true);boolean on=p.getBoolean("job103_on",false);if(!on){String last=p.getString("job103_last","");if(!last.isEmpty())note("Senaste pass:\n"+last);btn("▶ Starta jobbpass",()->{p.edit().putBoolean("job103_on",true).putLong("job103_t",System.currentTimeMillis()).putInt("job103_b",level()).putFloat("job103_temp",temp()).putFloat("job103_max",temp()).apply();saveBatterySample101();toast("Jobbpass startat");job103();});return;}long ms=Math.max(1,System.currentTimeMillis()-p.getLong("job103_t",System.currentTimeMillis()));double hours=ms/3600000d;int b0=p.getInt("job103_b",level()),used=Math.max(0,b0-level());float startT=p.getFloat("job103_temp",temp()),mx=Math.max(p.getFloat("job103_max",temp()),temp());p.edit().putFloat("job103_max",mx).apply();double ph=used/hours;note("🟢 Aktivt • "+(ms/60000)+" min\n🔋 "+b0+"% → "+level()+"% • "+String.format(Locale.ROOT,"%.1f",ph)+" %/tim\n🌡️ Start "+fmt(startT)+"°C • topp "+fmt(mx)+"°C");btn("📍 Spara kontrollpunkt",()->{float m=Math.max(p.getFloat("job103_max",temp()),temp());p.edit().putFloat("job103_max",m).apply();saveBatterySample101();toast("Kontrollpunkt sparad");job103();});btn("📍 Öppna Google Maps",()->launchPkg100("com.google.android.apps.maps","Google Maps"));btn("⏹ Avsluta jobbpass",()->{long dur=Math.max(1,System.currentTimeMillis()-p.getLong("job103_t",System.currentTimeMillis()));double h=dur/3600000d;int start=p.getInt("job103_b",level());int drain=Math.max(0,start-level());float max=Math.max(p.getFloat("job103_max",temp()),temp());String r=(dur/60000)+" min • "+start+"→"+level()+"% • "+String.format(Locale.ROOT,"%.1f",drain/h)+" %/tim • max "+fmt(max)+"°C";p.edit().putBoolean("job103_on",false).putString("job103_last",r).apply();log("Jobbpass 2.0: "+r);saveBatterySample101();job103();});}

 void graphs103(){saveBatterySample101();base("📊 GRAFER & HISTORIK","Senaste lokala mätpunkterna",true);ArrayList<Float>b=new ArrayList<>(),t=new ArrayList<>();String raw=p.getString("battery_history101","");for(String line:raw.split("\n")){try{String[]x=line.split(" • ");if(x.length>=3){b.add(Float.parseFloat(x[1].replace("%","")));t.add(Float.parseFloat(x[2].replace("°C","")));}}catch(Exception e){}}Collections.reverse(b);Collections.reverse(t);sec("🔋 Batteri %");addChart103(b,0,100,"%");sec("🌡️ Temperatur °C");addChart103(t,20,50,"°C");if(b.size()<3)note("Spara några fler mätningar för en tydligare trend.");btn("Spara mätpunkt nu",()->{saveBatterySample101();graphs103();});}
 void addChart103(ArrayList<Float>v,float lo,float hi,String unit){if(v.isEmpty()){note("Ingen data ännu.");return;}MetricView103 m=new MetricView103(this,v,lo,hi);root.addView(m,new android.widget.LinearLayout.LayoutParams(-1,260));float min=Collections.min(v),max=Collections.max(v),last=v.get(v.size()-1);note("Min "+fmt(min)+unit+" • Max "+fmt(max)+unit+" • Senast "+fmt(last)+unit+" • "+v.size()+" punkter");}
 class MetricView103 extends View{ArrayList<Float>v;float lo,hi;Paint p1=new Paint(1),grid=new Paint(1);MetricView103(Context c,ArrayList<Float>x,float a,float b){super(c);v=x;lo=a;hi=b;p1.setColor(GREEN);p1.setStrokeWidth(5);p1.setStyle(Paint.Style.STROKE);grid.setColor(Color.DKGRAY);grid.setStrokeWidth(2);}protected void onDraw(Canvas c){super.onDraw(c);float w=getWidth(),h=getHeight(),pad=18;c.drawLine(pad,h-pad,w-pad,h-pad,grid);c.drawLine(pad,pad,pad,h-pad,grid);if(v.size()<2)return;Path path=new Path();for(int i=0;i<v.size();i++){float x=pad+(w-2*pad)*i/(v.size()-1f);float n=Math.max(lo,Math.min(hi,v.get(i)));float y=h-pad-(h-2*pad)*(n-lo)/(hi-lo);if(i==0)path.moveTo(x,y);else path.lineTo(x,y);}c.drawPath(path,p1);}}

 void chargeLab103(){base("🔋 LADDNINGSANALYS","Sessioner • hastighet • temperatur",true);boolean on=p.getBoolean("chg103_on",false);if(!on){String hist=p.getString("chg103_hist","");if(!hist.isEmpty())note("Senaste sessioner:\n"+hist);btn("▶ Starta laddsession",()->{p.edit().putBoolean("chg103_on",true).putLong("chg103_t",System.currentTimeMillis()).putInt("chg103_b",level()).putFloat("chg103_temp",temp()).apply();toast("Laddsession startad");chargeLab103();});}else{long ms=Math.max(1,System.currentTimeMillis()-p.getLong("chg103_t",System.currentTimeMillis()));int b0=p.getInt("chg103_b",level()),gain=level()-b0;float t0=p.getFloat("chg103_temp",temp());double ph=gain/(ms/3600000d);note("🟢 Session aktiv • "+(ms/60000)+" min\n🔋 "+b0+"% → "+level()+"% • "+String.format(Locale.ROOT,"%.1f",ph)+" %/tim\n🌡️ "+fmt(t0)+"°C → "+fmt(temp())+"°C\nStatus: "+charge());btn("⏹ Avsluta och spara",()->finishCharge103());}btn("Battery Health",()->batteryHealth());btn("Charging Test Pro",()->battery89());}
 void finishCharge103(){long ms=Math.max(1,System.currentTimeMillis()-p.getLong("chg103_t",System.currentTimeMillis()));int b0=p.getInt("chg103_b",level()),gain=level()-b0;float t0=p.getFloat("chg103_temp",temp()),dt=temp()-t0;double ph=gain/(ms/3600000d);String row=new SimpleDateFormat("MM-dd HH:mm",Locale.getDefault()).format(new Date())+" • "+(ms/60000)+" min • "+b0+"→"+level()+"% • "+String.format(Locale.ROOT,"%.1f",ph)+" %/tim • ΔT "+(dt>=0?"+":"")+fmt(dt)+"°C";String old=p.getString("chg103_hist","");String all=row+(old.isEmpty()?"":"\n"+old);String[]ls=all.split("\n");StringBuilder out=new StringBuilder();for(int i=0;i<Math.min(8,ls.length);i++){if(i>0)out.append('\n');out.append(ls[i]);}p.edit().putBoolean("chg103_on",false).putString("chg103_hist",out.toString()).apply();log("Laddsession: "+row);chargeLab103();}

